def date_label(iso, lang):
    y, m, d = [int(x) for x in iso.split("-")]
    mon = MONTHS[lang][m - 1]
    if lang == "en":
        return f"{d} {mon} {y}"
    if lang == "de":
        return f"{d}. {mon} {y}"
    return f"{d} {mon} {y}"


